import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Repeating Sections (Repeater Controls) in AL","description":"","frontmatter":{},"headers":[],"relativePath":"pages-and-user-interfaces/repeating-sections.md","filePath":"pages-and-user-interfaces/repeating-sections.md"}`),a={name:`pages-and-user-interfaces/repeating-sections.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="repeating-sections-repeater-controls-in-al" tabindex="-1">Repeating Sections (Repeater Controls) in AL <a class="header-anchor" href="#repeating-sections-repeater-controls-in-al" aria-label="Permalink to “Repeating Sections (Repeater Controls) in AL”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>In Business Central, a <strong>Repeater</strong> is a layout control used to display multiple records in a tabular format, with each record appearing as a separate row.</p><p>For example, imagine we have a <code>Product</code> table containing the following records:</p><table tabindex="0"><thead><tr><th>No.</th><th>Name</th><th style="text-align:right;">Unit Price</th><th style="text-align:right;">Inventory</th></tr></thead><tbody><tr><td>P001</td><td>Laptop</td><td style="text-align:right;">75000</td><td style="text-align:right;">15</td></tr><tr><td>P002</td><td>Keyboard</td><td style="text-align:right;">2500</td><td style="text-align:right;">40</td></tr><tr><td>P003</td><td>Mouse</td><td style="text-align:right;">1200</td><td style="text-align:right;">65</td></tr></tbody></table><p>We can use a Repeater control to display these records on a Product List page.</p><p>Instead of manually creating a row for every product, Business Central automatically generates rows based on the records retrieved from the source table.</p><p><strong>Key idea:</strong> A Repeater defines a collection of columns that Business Central uses to display multiple records.</p><h2 id="declaring-a-repeater-control" tabindex="-1">Declaring a Repeater Control <a class="header-anchor" href="#declaring-a-repeater-control" aria-label="Permalink to “Declaring a Repeater Control”">​</a></h2><p>A Repeater is declared using the <code>repeater</code> keyword inside the <code>layout</code> section of a page object.</p><p><strong>Syntax:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>repeater(ControlName)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Field controls</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><code>repeater</code> declares the control.</li><li><code>ControlName</code> identifies the repeater.</li><li>The body contains the fields that should appear as columns.</li></ul><h3 id="practical-example" tabindex="-1">Practical Example <a class="header-anchor" href="#practical-example" aria-label="Permalink to “Practical Example”">​</a></h3><p>Let&#39;s create a Product List page using our existing <code>Product</code> table.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50100 ProductList</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = List;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    Caption = &#39;Products&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        area(Content)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            repeater(General)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                field(&quot;No.&quot;; Rec.&quot;No.&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(Name; Rec.Name)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(&quot;Unit Price&quot;; Rec.&quot;Unit Price&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(Inventory; Rec.Inventory)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s understand what happens:</p><ol><li><code>PageType = List</code> defines the page as a List page.</li><li><code>SourceTable = Product</code> specifies where the records come from.</li><li><code>repeater(General)</code> defines the repeating section.</li><li>Each <code>field</code> declaration defines a column in the list.</li><li>Business Central generates a row for each product record.</li></ol><p>The resulting page displays the products in a tabular format.</p><h2 id="understanding-how-repeaters-work" tabindex="-1">Understanding How Repeaters Work <a class="header-anchor" href="#understanding-how-repeaters-work" aria-label="Permalink to “Understanding How Repeaters Work”">​</a></h2><p>The important thing to understand is that <strong>the Repeater does not retrieve records itself</strong>.</p><p>Instead:</p><ul><li><code>SourceTable</code> establishes the page&#39;s data source.</li><li>Business Central retrieves the records according to the page&#39;s filters and view.</li><li>The Repeater defines how those records are presented.</li><li>Each field control determines which value appears in its corresponding column.</li></ul><p>For example:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Product Table</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>     | SourceTable = Product</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>Product List Page</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>     | Repeater</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>     |-- No.</span></span>
<span class="line"><span>     |-- Name</span></span>
<span class="line"><span>     |-- Unit Price</span></span>
<span class="line"><span>     |-- Inventory</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>Business Central displays each record as a row.</span></span></code></pre></div><p>This is why you don&#39;t need to write a loop to generate the rows manually.</p><h2 id="where-are-repeaters-used" tabindex="-1">Where Are Repeaters Used? <a class="header-anchor" href="#where-are-repeaters-used" aria-label="Permalink to “Where Are Repeaters Used?”">​</a></h2><p>Repeaters are particularly important when developing collection-oriented pages.</p><p>Common examples include:</p><table tabindex="0"><thead><tr><th>Page Type</th><th>Example</th></tr></thead><tbody><tr><td><code>List</code></td><td>Customer List, Vendor List, Item List</td></tr><tr><td><code>Worksheet</code></td><td>Item Journal, General Journal</td></tr><tr><td><code>ListPart</code></td><td>Sales Order Lines, embedded lists in FactBoxes</td></tr></tbody></table><p><strong>Important considerations:</strong></p><ul><li>A List page must contain a single Repeater group.</li><li>Repeaters are supported on collection-oriented pages such as List, Worksheet, and ListPart.</li><li>Repeaters are not intended for entity-oriented pages such as Card and Document.</li><li>If you want to display a list inside a Card or Document page, create a ListPart containing a Repeater and embed that ListPart in the parent page.</li></ul><p>For example, a Sales Order Document page can contain a ListPart displaying its sales order lines. This is an important distinction when designing Business Central interfaces.</p><h2 id="repeater-specific-properties" tabindex="-1">Repeater-Specific Properties <a class="header-anchor" href="#repeater-specific-properties" aria-label="Permalink to “Repeater-Specific Properties”">​</a></h2><p>Repeater controls support additional properties that influence how records are displayed.</p><p>Some worth recognizing include:</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><code>ShowCaption</code></td><td>Determines whether the repeater displays its caption.</td></tr><tr><td><code>ShowAsTree</code></td><td>Displays the repeater records in a hierarchical tree structure.</td></tr><tr><td><code>IndentationColumn</code></td><td>Specifies the source-table field that determines the indentation level of records.</td></tr><tr><td><code>IndentationControls</code></td><td>Specifies which columns should be indented in a hierarchical list.</td></tr></tbody></table><p>These properties are useful when designing more specialized list interfaces.</p><p>For now, focus on understanding the basic Repeater structure. We can explore hierarchical lists and their properties when needed.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li>A Repeater is a layout control used to display multiple records in rows and columns.</li><li>It is declared using the <code>repeater</code> keyword.</li><li>Fields declared inside a Repeater become columns in the resulting list.</li><li>Business Central automatically generates rows based on the records retrieved from the page&#39;s source table.</li><li>You don&#39;t need to manually loop through records to generate the rows.</li><li>Repeaters are primarily used on List, Worksheet, and ListPart pages.</li><li>To display a repeating section inside a Card or Document page, use an embedded ListPart.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><p><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-repeater-controls" target="_blank" rel="noreferrer">Microsoft Learn – Working with Repeater Controls</a></p>`,43)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};